package com.dpworld.fms.dispatch;
import com.dpworld.fms.routing.Route; import java.time.*; import java.util.*; import java.util.concurrent.*;
public final class DispatchService { public interface CommandPublisher{void publish(Command command);} public record Command(UUID commandId,UUID jobId,UUID assetId,Route route,String destination,Instant timestamp,String correlationId,int attempt){} private final CommandPublisher publisher;private final int maxAttempts;private final ConcurrentMap<UUID,Attempt> attempts=new ConcurrentHashMap<>(); public DispatchService(CommandPublisher publisher,int maxAttempts){this.publisher=publisher;this.maxAttempts=maxAttempts;} public Attempt dispatch(UUID job,UUID asset,Route route,String destination,String correlation){var existing=attempts.get(job);if(existing!=null&&existing.acknowledged())return existing;int number=existing==null?1:existing.number()+1;if(number>maxAttempts)throw new IllegalStateException("dispatch attempts exhausted");var attempt=new Attempt(UUID.randomUUID(),job,number,Instant.now(),false);attempts.put(job,attempt);publisher.publish(new Command(attempt.id(),job,asset,route,destination,Instant.now(),correlation,number));return attempt;} public void acknowledge(UUID job){attempts.computeIfPresent(job,(k,a)->new Attempt(a.id(),a.jobId(),a.number(),a.sentAt(),true));} public Optional<Attempt> attempt(UUID job){return Optional.ofNullable(attempts.get(job));} public record Attempt(UUID id,UUID jobId,int number,Instant sentAt,boolean acknowledged){} }
